// apps/web/components/ui/Toast.tsx
import * as React from 'react';
import { createPortal } from 'react-dom';
import { CheckCircle, XCircle, Info, AlertTriangle, X } from 'lucide-react';
import { cn } from '@/lib/cn';

const ToastContext = React.createContext<{
  toast: (opts: ToastOptions) => void;
} | null>(null);

export type ToastOptions = {
  title: string;
  description?: string;
  variant?: 'default' | 'success' | 'error' | 'info' | 'warning';
  duration?: number;
};

export function ToastProvider({ children }: { children: React.ReactNode }) {
  const [toasts, setToasts] = React.useState<ToastOptions[]>([]);

  const toast = React.useCallback((opts: ToastOptions) => {
    setToasts((prev) => [...prev, opts]);
    setTimeout(() => {
      setToasts((prev) => prev.slice(1));
    }, opts.duration || 4000);
  }, []);

  return (
    <ToastContext.Provider value={{ toast }}>
      {children}
      {createPortal(
        <div className="fixed bottom-6 right-6 z-50 space-y-3">
          {toasts.map((t, i) => (
            <Toast key={i} {...t} />
          ))}
        </div>,
        typeof window !== 'undefined' ? document.body : ({} as any)
      )}
    </ToastContext.Provider>
  );
}

export function useToast() {
  const ctx = React.useContext(ToastContext);
  if (!ctx) throw new Error('useToast must be used within ToastProvider');
  return ctx;
}

function Toast({ title, description, variant = 'default' }: ToastOptions) {
  let Icon = Info;
  let color = 'bg-card text-foreground';
  if (variant === 'success') {
    Icon = CheckCircle;
    color = 'bg-success text-white';
  } else if (variant === 'error') {
    Icon = XCircle;
    color = 'bg-destructive text-destructive-foreground';
  } else if (variant === 'warning') {
    Icon = AlertTriangle;
    color = 'bg-warning text-foreground';
  }
  return (
    <div
      className={cn(
        'flex items-start gap-3 rounded-lg shadow-lg p-4 border border-border min-w-[280px] max-w-xs',
        color
      )}
      role="status"
      aria-live={variant === 'error' ? 'assertive' : 'polite'}
    >
      <Icon className="w-5 h-5 mt-0.5" aria-hidden="true" />
      <div className="flex-1">
        <div className="font-medium text-base">{title}</div>
        {description && <div className="text-sm mt-1">{description}</div>}
      </div>
      <button
        className="ml-2 p-1 rounded-full hover:bg-muted focus-visible:ring-2 focus-visible:ring-primary"
        aria-label="Dismiss toast"
        tabIndex={0}
      >
        <X className="w-4 h-4" aria-hidden="true" />
      </button>
    </div>
  );
}

